INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (7,7,'["Comment construisez-vous un tableau de bord de gestion pour suivre la performance financière d''une structure publique comme l''ADER, et quels indicateurs clés y intégreriez-vous en priorité ?", "Face à un écart significatif entre le budget prévisionnel et l''exécution réelle en cours d''exercice, quelle démarche analytique et corrective mettez-vous en place ?", "Quelles sont, selon vous, les spécificités du contrôle de gestion dans un établissement public par rapport au secteur privé, notamment en matière de comptabilité analytique et de mesure de la performance ?", "Au cours de vos 5 années d''expérience, pouvez-vous citer une mission de contrôle de gestion dont vous êtes particulièrement fier et expliquer votre valeur ajoutée concrète ?", "Avez-vous déjà piloté ou participé à l''élaboration d''un business plan ou d''un budget annuel ? Décrivez votre rôle et la méthodologie utilisée ?", "Comment avez-vous géré une situation où vos analyses financières ont suscité des résistances de la part d''équipes opérationnelles ou de la direction ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès aujourd''hui, et qu''est-ce qui vous attire spécifiquement dans le passage vers un établissement public de développement régional ?", "Dans 3 à 5 ans, comment envisagez-vous l''évolution de votre rôle de Contrôleur de Gestion au sein d''une structure comme l''ADER ?", "Que savez-vous des missions et des axes stratégiques de l''ADER Fès-Meknès, et comment le contrôle de gestion peut-il, selon vous, contribuer directement à l''atteinte de ses objectifs de développement régional ?", "La régionalisation avancée au Maroc confère aux agences régionales un rôle croissant dans l''investissement et l''attractivité territoriale — quels défis financiers et de gouvernance cela implique-t-il pour un contrôleur de gestion ?"]','[]','{}','2026-08-27 13:26:46.335053') ON CONFLICT (id) DO NOTHING;